import React, { Component } from "react";
import { Card, CardBody, CardHeader, Col, Row, Table } from "reactstrap";
import { fetchLogs, fetchLogsPaginated, deleteChangeLogItem } from "../../actions/utils";
import { connect } from "react-redux";
import { bindActionCreators } from "redux";
// import Moment from 'react-moment';
import Pagination2 from "react-js-pagination";
import { FormattedMessage, FormattedDate } from "react-intl";

class AdminLogs extends Component {
	constructor (props) {
		super(props);
		this.state = {
			showModal        : false,
			processorCreated : false,
			showUpdateModal  : false,
			activePage       : 1,
		};
		this.handlePageChange = this.handlePageChange.bind(this);
	}
	handlePageChange = (pageNumber) => {
		let pageNumberParam = pageNumber - 1;
		this.props.fetchLogsPaginated(pageNumberParam);
		this.setState({ activePage: pageNumber });
	};

	componentDidMount () {
		this.props.fetchLogs();
	}

	componentDidUpdate () {
		console.log("THE PROPS:", this.props);
	}

	onSubmit = (values) => {
		this.props.createProcessor(values);
		this.closeModal();
	};

	updateProcessor = (id) => {
		this.setState({ showUpdateModal: !this.state.showUpdateModal });
		this.props.getOneProcessor(id);
	};

	closeUpdateModal = () => {
		this.setState({ showUpdateModal: !this.state.showUpdateModal });
	};

	onSubmitUpdate = (values) => {
		this.props.updateProcessor(values);
		this.closeUpdateModal();
	};
	toggle = () => {
		this.setState({ showModal: !this.state.showModal });
	};
	closeModal = () => {
		this.setState({ showModal: !this.state.showModal });
	};
	deleteProcessor = (id) => {
		this.props.deleteProcessor(id);
	};

	render () {
		return (
			<div className='animated fadeIn'>
				<Row>
					<Col>
						<Card>
							<CardHeader>
								<i className='fa fa-file' />{" "}
								<FormattedMessage id='File Logs' defaultMessage='File Logs' />
							</CardHeader>
							<CardBody>
								<Table
									hover
									bordered
									striped
									responsive
									size='sm'
									className='table-outline mb-0 d-sm-table'
								>
									<thead className='thead-light'>
										<tr>
											<th>
												<FormattedMessage id='Date' defaultMessage='Date' />
											</th>
											<th>
												<FormattedMessage id='File Name' defaultMessage='File Name' />
											</th>
											<th>
												<FormattedMessage id='Error Message' defaultMessage='Error Message' />
											</th>
											<th className={"px-2"} style={{ whiteSpace: "nowrap", width: "15px" }}>
												<FormattedMessage id='Status' defaultMessage='Status' />
											</th>
										</tr>
									</thead>
									<tbody>
										{this.props.fileLogs ? (
											[
												this.props.fileLogs.data.content.length > 0 ? (
													this.props.fileLogs.data.content.map((item, index) => (
														<tr key={index + 1}>
															<td>
																<FormattedDate
																	value={new Date(item.processedOn * 1000)}
																	year='numeric'
																	month='long'
																	day='numeric'
																	weekday='long'
																/>
															</td>
															<td>{item.fileName}</td>
															<td>
																{item.message ? (
																	<span>{item.message}</span>
																) : (
																	<span>N/A</span>
																)}
															</td>
															<td>
																{item.failed ? (
																	<span className='d-flex justify-content-center aligin-item-center text-danger'>
																		<i class='fa fa-times' aria-hidden='true' />
																	</span>
																) : (
																	<span className='d-flex justify-content-center aligin-item-center text-success'>
																		<i
																			className='fa fa-check text-success'
																			aria-hidden='true'
																		/>
																	</span>
																)}
															</td>
														</tr>
													))
												) : (
													<tr key={1}>
														<td colSpan='6'>
															<p className='text-center text-danger'>
																There are no file logs at the moment.
															</p>
														</td>
													</tr>
												),
											]
										) : (
											[ null ]
										)}
									</tbody>
								</Table>

								{this.props.fileLogs ? (
									<nav>
										<Pagination2
											activePage={this.state.activePage}
											itemsCountPerPage={10}
											totalItemsCount={
												this.props.fileLogs ? this.props.fileLogs.data.totalElements : null
											}
											pageRangeDisplayed={5}
											onChange={this.handlePageChange}
										/>
									</nav>
								) : (
									""
								)}
							</CardBody>
						</Card>
					</Col>
				</Row>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	return {
		fileLogs : state.utils.fileLogs,
	};
};

const mapDispatchToProps = (dispatch) => {
	return bindActionCreators(
		{
			fetchLogs,
			fetchLogsPaginated,
			deleteChangeLogItem,
		},
		dispatch,
	);
};

export default connect(mapStateToProps, mapDispatchToProps)(AdminLogs);
